async function readImport(file){if(!file)return;try{if(!/\.(xlsx|xls)$/i.test(file.name)||file.size>10485760)throw Error('请选择10 MiB以内的XLSX或XLS文件');const formData=new FormData();formData.append('file',file);$('load-status').textContent='正在识别Excel字段…';const preview=await api('employee-center/import/preview','POST',formData);importData={headers:preview.headers,rows:preview.rows,mapping:preview.headers.map(h=>Object.keys(aliases).find(k=>aliases[k].includes(h.trim()))||''),mapped:[],filename:file.name,stage:3,done:false};const saved=cfg.history.find(h=>h.type==='mapping'&&JSON.stringify(h.headers)===JSON.stringify(importData.headers));if(saved)importData.mapping=saved.mapping.slice();filters={};tab='';currentPage=1;render();toast('文件读取完成，请核对字段映射');}catch(error){toast(error.message);}finally{$('load-status').textContent='职工批量导入 · 校验完成后再写入档案';}}
