 if(section!=='departments'){const exposureMode=section==='exposures';const positions=cfg.positions.filter(p=>!filters.search||(p.name+p.exposure+p.code).includes(filters.search));const rows=paginate(positions).map(p=>'<tr><td><b>'+e(p.name)+'</b></td><td>'+e(p.code||'—')+'</td><td>'+e(p.exposure||'待配置')+'</td><td>'+e(p.description||'—')+'</td><td>'+n(people.filter(x=>x.job===p.name).length)+'</td><td>'+badge(p.enabled===false?'停用':'启用',p.enabled===false?'':'completed')+'</td><td>'+link('编辑','edit-position',p.id)+link(p.enabled===false?'启用':'停用','toggle-position',p.id)+'</td></tr>');$('app').innerHTML=tabs+cards+'<div class="ec-toolbar"><div class="ec-actions">'+btn(exposureMode?'＋ 新建岗位接害配置':'＋ 新增岗位','new-position','primary')+btn('⇩ 导出岗位','export-positions')+'</div></div>'+panel(exposureMode?'岗位职业危害因素':'企业岗位管理',searchForm('')+table(['岗位名称','岗位编码','职业危害因素','职责 / 防护说明','在岗人数','状态','操作'],rows)+pager(positions.length))+(exposureMode?panel('职业危害配置说明','<div class="ec-help">职业危害因素用于岗位资料维护，支持粉尘、噪声、高温、振动及其他已登记因素。岗位配置不会自动覆盖职工原有的接害记录；人员调岗时请核对实际接触情况。</div>'):'');return;}
