 const tree='<div class="ec-tree"><button type="button" data-org="" class="'+(!selectedOrg?'active':'')+'">▣ 企业组织 <small>'+total+'人</small></button>'+cfg.departments.map(d=>'<button type="button" class="child '+(d.id===selectedOrg?'active':'')+'" data-org="'+e(d.id)+'"><span>▰ '+e(d.name)+'</span><small>'+people.filter(p=>p.org===d.name).length+'</small></button>').join('')+'</div><div class="ec-actions" style="margin-top:12px">'+btn('＋ 新建部门','new-department','primary')+'</div>';
