 if(act==='follow-one'||act==='follow-selected'){if(act==='follow-selected'&&!selected.size)throw Error('请先选择职工');if(dialog)dialog.close();window.DigitalWorkerDispatch.assign('follow',()=>toast('随访任务已创建'));}
 if(act==='batch-group')batchAssign('groups');if(act==='batch-tag')batchAssign('tags');
 if(act==='export-people'){const rows=employeeFilter();download('职工列表.csv',[['姓名','工号','性别','年龄','单位','班组','岗位','电话','职业暴露','风险等级','档案状态','小程序状态'],...rows.map(p=>[p.name,p.code,p.sex,p.age,p.org,p.team,p.job,p.phone,p.exposure,riskNames[p.risk],statusNames[p.status],p.bound?'已绑定':'未绑定'])]);}
 if(act==='new-meta'||act==='edit-meta')editMeta(id);
 if(act==='view-meta')viewMeta(id);if(act==='members')viewMeta(id,true);
 if(act==='toggle-meta'){const key=pageType==='groups'?'groups':'tags';await update(()=>{const item=cfg[key].find(x=>x.id===id);item.enabled=item.enabled===false;item.updatedAt=new Date().toISOString();});render();toast('状态已更新');}
 if(act==='smart-meta'||act==='rules-meta')smartMeta();
 if(act==='export-meta'){const key=pageType==='groups'?'groups':'tags';download((key==='groups'?'职工分组':'职工标签')+'.csv',[['名称','分类','规则','关联人数','状态'],...cfg[key].map(x=>[x.name,x.kind,ruleText(x),members(x).length,x.enabled===false?'停用':'启用'])]);}
 if(act==='tag-people'){form('选择批量标签','<div class="ec-form-grid">'+select('tag','选择标签',Object.fromEntries(cfg.tags.map(t=>[t.id,t.name])))+'</div>',async body=>{setTimeout(()=>{const item=cfg.tags.find(t=>t.id===body.tag);memberPicker('批量打标 · '+item.name,[...(item.members||[])],async ids=>update(()=>{item.members=ids;item.updatedAt=new Date().toISOString();}));},0);});}
 if(act==='select-binding'){selectedBinding=id;render();}
 if(act==='issue-code')issueCode(id);if(act==='unbind')unbind(id);if(act==='binding-history')await bindingHistory(id);if(act==='match-binding')matchBinding(id);if(act==='select-match'){selectedBinding=id;if(dialog)dialog.close();render();}
 if(act==='choose-file')$('ec-file').click();if(act==='import-template'){const a=document.createElement('a');a.href=base+'ehr/api/employee-center/import/template';a.download='职工导入模板.xlsx';a.click();}
 if(act==='validate-import'){if(!importData.rows.length)throw Error('请先上传Excel文件');importData.stage=5;render();toast('校验完成，请检查预览结果');}
 if(act==='save-mapping'){if(!importData.headers.length)throw Error('请先上传Excel文件');await update(()=>cfg.history.unshift({id:uid(),type:'mapping',headers:importData.headers,mapping:importData.mapping,name:'字段映射模板',time:new Date().toISOString()}));toast('映射模板已保存');}
 if(act==='fix-import')fixImport(Number(id));if(act==='issue-filter'){tab=id;currentPage=1;render();}
 if(act==='start-import')startImport();if(act==='export-errors')download('导入错误数据.csv',[[...Object.values(importFields),'问题说明'],...importData.mapped.filter(r=>r.issues.length).map(r=>[...Object.keys(importFields).map(k=>r.body[k]||''),r.issues.join('；')])]);
 if(act==='import-history')show('历史导入记录',cfg.history.filter(h=>h.type==='import').map(h=>'<div class="ec-history"><b>'+e(h.name)+'</b>'+e(h.time)+' · 成功 '+n(h.count)+' 人</div>').join('')||'<div class="ec-empty">暂无导入记录</div>');
